Below you see a pydantic model named LeagueSchedule. Return a json that, when parsed to a dict, is compatible with the model. Here is the pydantic config:

```python
from pydantic import (
    BaseModel, ConfigDict, Field, field_validator,
    model_validator, computed_field, ValidationError,
    StrictInt, StrictStr
)
from typing import List, Dict, Optional, Any, Annotated
from datetime import datetime, timedelta
from enum import Enum

class DivEnum(str, Enum):
    A = 'A'
    B = 'B'
    C = 'C'

class SeasonInfo(BaseModel):
    year: StrictInt
    name: StrictStr
    division: DivEnum
    start_date: datetime = Field(alias='startDate')
    end_date: datetime = Field(alias='endDate')

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @model_validator(mode='after')
    def check_dates(cls, m):
        if m.end_date <= m.start_date:
            raise ValidationError([
                {'loc': ('endDate',), 'msg': 'endDate must be after startDate', 'type': 'value_error'}
            ], model=SeasonInfo)
        return m

class Player(BaseModel):
    id: StrictInt
    name: StrictStr
    age: StrictInt
    jersey_number: StrictInt = Field(alias='jerseyNumber')

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('age')
    def age_range(cls, v):
        if v < 5 or v > 60:
            raise ValueError('age must be between 5 and 60')
        return v

    @field_validator('jersey_number')
    def jersey_valid(cls, v):
        if not 0 <= v <= 99:
            raise ValueError('jersey_number must be 0-99')
        return v

class Venue(BaseModel):
    id: StrictInt
    name: StrictStr
    address: StrictStr
    capacity: StrictInt
    timezone: StrictStr

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('capacity')
    def cap_min(cls, v):
        if v < 10:
            raise ValueError('capacity must be at least 10')
        return v

class Team(BaseModel):
    id: StrictInt
    name: StrictStr
    players: List[Player]
    home_venue: Venue = Field(alias='homeVenue')
    captain_id: StrictInt = Field(alias='captainId')

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('players')
    def roster_size(cls, v):
        if not (5 <= len(v) <= 20):
            raise ValueError('players count must be 5-20')
        return v

    @model_validator(mode='after')
    def check_captain(cls, m):
        if not any(p.id == m.captain_id for p in m.players):
            raise ValidationError([
                {'loc': ('captainId',), 'msg': 'captainId must match a player id', 'type': 'value_error'}
            ], model=Team)
        return m

class Referee(BaseModel):
    id: StrictInt
    name: StrictStr
    qualifications: List[DivEnum]

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('qualifications')
    def need_one(cls, v):
        if not v:
            raise ValueError('must have at least one division qualification')
        return v

class Score(BaseModel):
    home: StrictInt
    away: StrictInt

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('home', 'away')
    def non_negative(cls, v):
        if v < 0:
            raise ValueError('score must be non-negative')
        return v

class Game(BaseModel):
    id: StrictInt
    sport: DivEnum
    home_team_id: StrictInt = Field(alias='homeTeamId')
    away_team_id: StrictInt = Field(alias='awayTeamId')
    venue_id: StrictInt = Field(alias='venueId')
    start_time: Annotated[datetime, Field(alias='startTime')]
    end_time: Annotated[datetime, Field(alias='endTime')]
    referee_ids: List[StrictInt] = Field(alias='refereeIds')
    score: Optional[Score]
    attendance: Optional[StrictInt] = 0

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @model_validator(mode='after')
    def check_times(cls, m):
        if m.end_time <= m.start_time:
            raise ValidationError([
                {'loc': ('endTime',), 'msg': 'endTime must be after startTime', 'type': 'value_error'}
            ], model=Game)
        return m

    @field_validator('attendance')
    def attend_nonneg(cls, v):
        if v is not None and v < 0:
            raise ValueError('attendance must be non-negative')
        return v

    @computed_field
    @property
    def duration(self) -> timedelta:
        return self.end_time - self.start_time

class Week(BaseModel):
    week_number: StrictInt = Field(alias='week')
    matches: List[Game] = Field(alias='games')

    model_config = ConfigDict(extra='forbid', validate_assignment=True)

    @field_validator('week_number')
    def week_positive(cls, v):
        if v < 1:
            raise ValueError('week must be >= 1')
        return v

class LeagueSchedule(BaseModel):
    season: SeasonInfo
    teams: List[Team]
    referees: List[Referee]
    games: List[Game]
    weeks: List[Week]
    metadata: Dict[StrictStr, Any] = {}

    model_config = ConfigDict(
        extra='forbid',
        validate_assignment=True,
        populate_by_name=True,
        str_strip_whitespace=True
    )

    @model_validator(mode='after')
    def cross_validate(cls, m):
        errors = []
        tmap = {t.id: t for t in m.teams}
        rmap = {r.id: r for r in m.referees}
        # game references
        for i, g in enumerate(m.games):
            base = ('games', i)
            if g.home_team_id not in tmap:
                errors.append({'loc': base + ('homeTeamId',), 'msg': 'unknown homeTeamId', 'type': 'value_error'})
            if g.away_team_id not in tmap:
                errors.append({'loc': base + ('awayTeamId',), 'msg': 'unknown awayTeamId', 'type': 'value_error'})
            for rid in g.referee_ids:
                if rid not in rmap:
                    errors.append({'loc': base + ('refereeIds',), 'msg': f'unknown referee {rid}', 'type': 'value_error'})
                elif g.sport not in rmap[rid].qualifications:
                    errors.append({'loc': base + ('refereeIds',), 'msg': f'referee {rid} not qualified for {g.sport}', 'type': 'value_error'})
        # week-game consistency
        total_week_games = sum(len(w.matches) for w in m.weeks)
        if total_week_games != len(m.games):
            errors.append({'loc': ('weeks',), 'msg': 'sum of week games must equal total games', 'type': 'value_error'})
        # no overlapping per venue
        by_venue: Dict[int, List[Game]] = {}
        for g in m.games:
            by_venue.setdefault(g.venue_id, []).append(g)
        for vid, gl in by_venue.items():
            gls = sorted(gl, key=lambda x: x.start_time)
            for prev, nxt in zip(gls, gls[1:]):
                if nxt.start_time < prev.end_time:
                    errors.append({'loc': ('games',), 'msg': f'overlap at venue {vid}', 'type': 'value_error'})
                    break
        if errors:
            raise ValidationError(errors, model=LeagueSchedule)
        return m

```

