import enum
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, field_validator, model_validator, ValidationError

class ActionEnum(str, enum.Enum):
    FORWARD = 'forward'
    DROP = 'drop'
    MIRROR = 'mirror'
    POLICE = 'police'

class AlgorithmEnum(str, enum.Enum):
    WRR = 'wrr'
    SP = 'sp'
    DRR = 'drr'
    CBQ = 'cbq'

class MatchTypeEnum(str, enum.Enum):
    IP = 'ip'
    TCP = 'tcp'
    UDP = 'udp'
    VXLAN = 'vxlan'
    MPLS = 'mpls'

class TokenBucket(BaseModel):
    bucket_size: int
    tokens_per_interval: int
    interval_ms: int

    @model_validator(mode='after')
    def check_bucket(cls, m):
        if m.bucket_size <= 0:
            raise ValueError('bucket_size must be positive')
        if m.tokens_per_interval <= 0:
            raise ValueError('tokens_per_interval must be positive')
        if m.interval_ms <= 0:
            raise ValueError('interval_ms must be positive')
        return m

class RateLimitConfig(BaseModel):
    committed_rate: float  # Mbps
    peak_rate: float       # Mbps
    burst_size: int        # bytes
    token_bucket: TokenBucket

    @model_validator(mode='after')
    def check_rates(cls, m):
        if m.committed_rate <= 0 or m.peak_rate <= 0:
            raise ValueError('Rates must be positive')
        if m.committed_rate > m.peak_rate:
            raise ValueError('committed_rate must not exceed peak_rate')
        if m.burst_size < 0:
            raise ValueError('burst_size must be non-negative')
        return m

class ShapingProfile(BaseModel):
    smoothing_coefficient: float
    max_concurrency: int
    jitter_buffer_ms: float

    @model_validator(mode='after')
    def check_profile(cls, m):
        if not 0.0 <= m.smoothing_coefficient <= 1.0:
            raise ValueError('smoothing_coefficient must be in [0.0, 1.0]')
        if m.max_concurrency <= 0:
            raise ValueError('max_concurrency must be positive')
        if m.jitter_buffer_ms < 0:
            raise ValueError('jitter_buffer_ms must be non-negative')
        return m

class BufferAllocation(BaseModel):
    min_buffers: int
    max_buffers: int
    dynamic: bool

    @model_validator(mode='after')
    def check_buffers(cls, m):
        if m.min_buffers < 0 or m.max_buffers < 0:
            raise ValueError('buffer counts must be non-negative')
        if m.min_buffers > m.max_buffers:
            raise ValueError('min_buffers must not exceed max_buffers')
        return m

class MatchCriterion(BaseModel):
    type: MatchTypeEnum
    value: str
    invert: bool = False

    @field_validator('value')
    def non_empty_value(cls, v):
        if not v or not v.strip():
            raise ValueError('value must be a non-empty string')
        return v

class QueueConfig(BaseModel):
    id: int
    name: str
    priority: int
    rate_limit: Optional[RateLimitConfig]
    shaping_profile: ShapingProfile
    buffer_allocation: BufferAllocation
    match_criteria: List[MatchCriterion]

    @model_validator(mode='after')
    def check_queue(cls, m):
        if m.id < 0:
            raise ValueError('queue id must be non-negative')
        if not m.name:
            raise ValueError('queue name must not be empty')
        if not 0 <= m.priority <= 10:
            raise ValueError('priority must be between 0 and 10')
        return m

class SchedulerConfig(BaseModel):
    name: str
    algorithm: AlgorithmEnum
    parameters: Dict[str, Any]

    @field_validator('name')
    def non_empty_name(cls, v):
        if not v.strip():
            raise ValueError('scheduler name must be non-empty')
        return v

class HFQoSPolicy(BaseModel):
    policy_id: str
    version: int
    default_action: ActionEnum
    queues: List[QueueConfig]
    schedulers: Dict[str, SchedulerConfig]
    global_rate_limit: Optional[RateLimitConfig]

    model_config = {
        'extra': 'forbid',
    }

    @field_validator('policy_id')
    def non_empty_policy_id(cls, v):
        if not v.strip():
            raise ValueError('policy_id must be non-empty')
        return v

    @model_validator(mode='after')
    def check_uniqueness(cls, m):
        ids = [q.id for q in m.queues]
        names = [q.name for q in m.queues]
        if len(ids) != len(set(ids)):
            raise ValueError('queue ids must be unique')
        if len(names) != len(set(names)):
            raise ValueError('queue names must be unique')
        return m

```

