```python
from typing import List, Literal, Optional
from pydantic import BaseModel, Field, model_validator, ValidationError, ConfigDict

class CPU(BaseModel):
    model_config = ConfigDict()
    model: str
    socket: Literal['AM4','AM5','LGA1200','LGA1700']
    supported_chipsets: List[str]
    tdp: int = Field(..., ge=1)
    compatible_motherboards: List[str]

class Motherboard(BaseModel):
    model_config = ConfigDict()
    model: str
    socket: Literal['AM4','AM5','LGA1200','LGA1700']
    chipset: str
    form_factor: Literal['ATX','MicroATX','MiniITX']
    memory_type: Literal['DDR4','DDR5']
    pcie_version: Literal['3.0','4.0','5.0']
    m2_slots: int = Field(..., ge=0)
    compatible_rams: List[str]

class RAM(BaseModel):
    model_config = ConfigDict()
    model: str
    memory_type: Literal['DDR4','DDR5']
    speed_mhz: int = Field(..., gt=0)

class GPU(BaseModel):
    model_config = ConfigDict()
    model: str
    pcie_version: Literal['3.0','4.0','5.0']
    tdp: int = Field(..., ge=1)
    connectors_8pin_required: int = Field(..., ge=0)
    length_mm: int = Field(..., gt=0)

class PSU(BaseModel):
    model_config = ConfigDict()
    model: str
    wattage: int = Field(..., ge=100)
    connectors_6pin: int = Field(..., ge=0)
    connectors_8pin: int = Field(..., ge=0)

class Storage(BaseModel):
    model_config = ConfigDict()
    model: str
    interface: Literal['SATA','NVMe','PCIe']
    capacity_gb: int = Field(..., ge=1)

class Cooler(BaseModel):
    model_config = ConfigDict()
    model: str
    type: Literal['air','liquid']
    height_mm: Optional[int] = None
    radiator_size_mm: Optional[Literal[120,240,360]] = None
    radiator_fan_count: Optional[int] = None

    @model_validator(mode='after')
    def check_fields(self):
        errors = []
        if self.type == 'air':
            if self.height_mm is None:
                errors.append({'loc': ('height_mm',), 'msg': 'height_mm required for air cooler', 'type': 'value_error'})
            if self.radiator_size_mm is not None or self.radiator_fan_count is not None:
                errors.append({'loc': ('radiator_size_mm',), 'msg': 'radiator fields forbidden for air cooler', 'type': 'value_error'})
        else:
            if self.radiator_size_mm is None or self.radiator_fan_count is None:
                errors.append({'loc': ('radiator_size_mm',), 'msg': 'radiator_size_mm and radiator_fan_count required for liquid cooler', 'type': 'value_error'})
            if self.height_mm is not None:
                errors.append({'loc': ('height_mm',), 'msg': 'height_mm forbidden for liquid cooler', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=type(self))
        return self

class Case(BaseModel):
    model_config = ConfigDict()
    model: str
    supported_form_factors: List[Literal['ATX','MicroATX','MiniITX']]
    max_cpu_cooler_height: int = Field(..., ge=20)
    supported_radiator_sizes: List[Literal[120,240,360]]
    max_gpu_length_mm: int = Field(..., ge=100)

class PCCompatSpec(BaseModel):
    model_config = ConfigDict(strict=True)
    cpus: List[CPU]
    motherboards: List[Motherboard]
    rams: List[RAM]
    gpus: List[GPU]
    psus: List[PSU]
    storages: List[Storage]
    cases: List[Case]
    coolers: List[Cooler]

    @model_validator(mode='after')
    def validate_all(self):
        errors = []
        mb_map = {mb.model: mb for mb in self.motherboards}
        ram_map = {r.model: r for r in self.rams}
        case_list = self.cases

        # CPU vs Motherboard
        for i, cpu in enumerate(self.cpus):
            for mb_name in cpu.compatible_motherboards:
                mb = mb_map.get(mb_name)
                if not mb:
                    errors.append({'loc': ('cpus', i, 'compatible_motherboards'), 'msg': f'Motherboard {mb_name} not defined', 'type': 'value_error'})
                else:
                    if mb.socket != cpu.socket:
                        errors.append({'loc': ('cpus', i, 'compatible_motherboards'), 'msg': f'Socket mismatch {cpu.model} vs {mb.model}', 'type': 'value_error'})
                    if mb.chipset not in cpu.supported_chipsets:
                        errors.append({'loc': ('cpus', i, 'supported_chipsets'), 'msg': f'Chipset {mb.chipset} unsupported by {cpu.model}', 'type': 'value_error'})
        # Motherboard vs RAM
        for i, mb in enumerate(self.motherboards):
            for ram_name in mb.compatible_rams:
                ram = ram_map.get(ram_name)
                if not ram:
                    errors.append({'loc': ('motherboards', i, 'compatible_rams'), 'msg': f'RAM {ram_name} not defined', 'type': 'value_error'})
                else:
                    if ram.memory_type != mb.memory_type:
                        errors.append({'loc': ('motherboards', i, 'memory_type'), 'msg': f'Memory type mismatch {mb.model} vs {ram.model}', 'type': 'value_error'})
        # NVMe slot count
        total_nvme_slots = sum(mb.m2_slots for mb in self.motherboards)
        nvme_count = sum(1 for s in self.storages if s.interface == 'NVMe')
        if nvme_count > total_nvme_slots:
            errors.append({'loc': ('storages',), 'msg': 'Not enough M.2 slots for NVMe drives', 'type': 'value_error'})
        # PSU capacity and connectors
        total_tdp = sum(c.tdp for c in self.cpus) + sum(g.tdp for g in self.gpus)
        required_8pin = sum(g.connectors_8pin_required for g in self.gpus)
        for i, psu in enumerate(self.psus):
            if psu.wattage < total_tdp * 1.2:
                errors.append({'loc': ('psus', i, 'wattage'), 'msg': f'Insufficient wattage {psu.model}', 'type': 'value_error'})
            if psu.connectors_8pin < required_8pin:
                errors.append({'loc': ('psus', i, 'connectors_8pin'), 'msg': 'Not enough 8-pin connectors', 'type': 'value_error'})
        # Cooler vs Case
        for i, cooler in enumerate(self.coolers):
            fits = False
            for case in case_list:
                if cooler.type == 'air' and cooler.height_mm <= case.max_cpu_cooler_height:
                    fits = True; break
                if cooler.type == 'liquid' and cooler.radiator_size_mm in case.supported_radiator_sizes:
                    fits = True; break
            if not fits:
                errors.append({'loc': ('coolers', i), 'msg': f'Cooler {cooler.model} does not fit any case', 'type': 'value_error'})
        # GPU vs Case
        for i, gpu in enumerate(self.gpus):
            if not any(gpu.length_mm <= case.max_gpu_length_mm for case in case_list):
                errors.append({'loc': ('gpus', i, 'length_mm'), 'msg': f'GPU {gpu.model} does not fit any case', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=type(self))
        return self

