from datetime import date, datetime, time
from decimal import Decimal
from enum import Enum
from typing import List, Optional, Literal, Dict, Union
import re

from pydantic import (
    BaseModel,
    StrictStr,
    StrictInt,
    Field,
    field_validator,
    model_validator,
    ValidationError,
)

class ScheduleStatus(str, Enum):
    PENDING = 'pending'
    IN_PROGRESS = 'in_progress'
    COMPLETED = 'completed'

class TaskCategory(str, Enum):
    CLEANING = 'cleaning'
    LINEN_CHANGE = 'linen_change'
    INSPECTION = 'inspection'
    REFILL = 'refill'

class Role(str, Enum):
    HOUSEKEEPER = 'housekeeper'
    SUPERVISOR = 'supervisor'

class HousekeepingWindow(str, Enum):
    MORNING = 'morning'
    AFTERNOON = 'afternoon'
    EVENING = 'evening'
    NIGHT = 'night'

class RatePlan(BaseModel):
    nightly_rate: Decimal = Field(..., gt=Decimal('0.00'))
    currency: Literal['USD', 'EUR', 'GBP']

    model_config = {'extra': 'forbid'}

class Contact(BaseModel):
    phone: StrictStr
    email: StrictStr

    model_config = {'extra': 'forbid'}

    @field_validator('phone')
    def validate_phone(cls, v: str) -> str:
        if not re.fullmatch(r'^\+?\d{7,15}$', v):
            raise ValueError('phone must be digits with optional leading +, length 7-15')
        return v

