        task_ids = {t.id for t in values.tasks}
        if len(task_ids) != len(values.tasks):
            raise ValueError('task ids must be unique')
        # days_tasks subset
        for lst in values.days_tasks.values():
            if any(i not in task_ids for i in lst):
                raise ValueError('days_tasks ids must exist in tasks')
        # supervisor required if in progress
