        if values.additional_services is not None and not values.additional_services:
            raise ValueError('additional_services cannot be empty')
        # special_requests in range
        if values.special_requests is not None:
            for req, d in values.special_requests.items():
                if d < ci or (co and d > co):
                    raise ValueError(f'special_request {req} date out of stay range')
        return values

