def version_control_processor(input_data):
    result = {"diff": [], "metrics": {}, "merged": None}

    def process(item, depth=0, path=""):
        changes = []

        if isinstance(item, dict):
            transformed = {}
            for k, v in sorted(item.items()):
                new_k = k.swapcase() if isinstance(k, str) else k
                if new_k != k:
                    changes.append({"path": path, "key": {"from": k, "to": new_k}})

                new_v, sub_changes = process(v, depth + 1, f"{path}.{k}")
                transformed[new_k] = new_v
                changes.extend(sub_changes)

            result["metrics"]["dict_count"] = result["metrics"].get("dict_count", 0) + 1
            return transformed, changes

        elif isinstance(item, list):
            transformed = []
            source = list(reversed(item)) if depth % 2 == 0 else item
            if depth % 2 == 0 and item:
                changes.append({"path": path, "list": "reversed"})

            for i, v in enumerate(source):
                new_v, sub_changes = process(v, depth + 1, f"{path}[{i}]")
                transformed.append(new_v)
                changes.extend(sub_changes)

            result["metrics"]["list_count"] = result["metrics"].get("list_count", 0) + 1
            return transformed, changes

        elif isinstance(item, str):
            if depth % 3 == 0:
                new_v = item.upper()
                op = "upper"
            elif depth % 3 == 1:
                new_v = item.lower()
                op = "lower"
            else:
                shift = depth % max(1, len(item))
                new_v = item[shift:] + item[:shift]
                op = "rotate"

            if new_v != item:
                changes.append({"path": path, "string": {"op": op, "from": item, "to": new_v}})

            result["metrics"]["string_count"] = result["metrics"].get("string_count", 0) + 1
            return new_v, changes

        elif isinstance(item, int):
            new_v = item + depth * (1 if item % 2 == 0 else -1)

            if new_v != item:
                changes.append({"path": path, "int": {"from": item, "to": new_v}})

            result["metrics"]["int_count"] = result["metrics"].get("int_count", 0) + 1
            return new_v, changes

        else:
            return item, changes

    result["merged"], all_changes = process(input_data)
    result["diff"] = all_changes[:10]  # Limit to 10 changes
    result["metrics"]["complexity"] = sum(result["metrics"].values())

    return result
